/* =============================================================================
   XuperTV 4.34.4  ->  LG webOS 4 (Chromium 53) fidelity reconstruction
   -----------------------------------------------------------------------------
   Scale convention taken from the decoded AndroidManifest:
       design_width       = 1920
       design_width_in_dp = 1280
   =>  1 design dp = 1.5 CSS px   |   1 sp = 1.5 CSS px   |   raw "px" = 1 CSS px
   Geometry below is CSS px at 1920x1080.
   Sources: res/layout/*.xml, res/values/{colors,dimens,styles}.xml,
            res/drawable (shapes / selectors), res/values-es/strings.xml
   ============================================================================= */

* { margin: 0; padding: 0; box-sizing: border-box; }

html, body {
  width: 1920px;
  height: 1080px;
  overflow: hidden;
  background: #000000;
  color: #ffffff;
  /* The APK bundles no UI font (only assets/amazingkids.otf for kids artwork).
     Android renders "sans-serif" (Roboto); webOS supplies its own sans face. */
  font-family: Roboto, "Helvetica Neue", Helvetica, Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  cursor: none;
}

img { border: 0; display: block; }
div, section, span { outline: none; }
#app { position: relative; width: 1920px; height: 1080px; overflow: hidden; }

.screen {
  position: absolute;
  left: 0; top: 0;
  width: 1920px; height: 1080px;
  display: none;
}
.screen.is-active { display: block; }

/* =============================================================================
   SPLASH SCREEN & LOGO OPTIMIZATIONS
   ============================================================================= */
.splash-screen {
  position: fixed;
  left: 0; top: 0;
  width: 100vw; height: 100vh;
  background: #050811 url(../media/ui/welcome/eclex_bg.jpg) center center / cover no-repeat !important;
  z-index: 9999 !important;
  display: -webkit-box;
  display: -ms-flexbox;
  display: flex;
  -webkit-box-orient: vertical;
  -webkit-box-direction: normal;
  -ms-flex-direction: column;
  flex-direction: column;
  -webkit-box-align: center;
  -ms-flex-align: center;
  align-items: center;
  -webkit-box-pack: center;
  -ms-flex-pack: center;
  justify-content: center;
  opacity: 1;
  -webkit-transition: opacity 0.5s ease;
  transition: opacity 0.5s ease;
  pointer-events: auto;
}
.splash-screen.is-hidden {
  opacity: 0;
  pointer-events: none;
}
.splash-content {
  text-align: center;
  padding: 38px 65px;
  background: rgba(5, 8, 17, 0.65);
  border-radius: 20px;
  box-shadow: 0 10px 45px rgba(0, 0, 0, 0.85);
  border: 1px solid rgba(212, 175, 55, 0.4);
}
.splash-title {
  font-family: 'Brush Script MT', 'Playfair Display', 'Georgia', 'Palatino Linotype', 'Segoe Script', cursive, serif;
  font-style: italic;
  font-size: 58px;
  font-weight: 700;
  color: #ffffff;
  letter-spacing: 2px;
  margin-bottom: 24px;
  text-shadow: 0 4px 18px rgba(0, 0, 0, 0.95), 0 0 25px rgba(245, 166, 35, 0.6), 0 0 40px rgba(0, 0, 0, 0.9);
}
.splash-version {
  display: none;
}
.splash-spinner {
  width: 50px;
  height: 50px;
  margin: 0 auto;
  border: 4px solid rgba(255, 255, 255, 0.2);
  border-top-color: #f5a623;
  border-radius: 50%;
  -webkit-animation: splash-spin 0.8s linear infinite;
  animation: splash-spin 0.8s linear infinite;
  box-shadow: 0 0 16px rgba(245, 166, 35, 0.5);
}
@-webkit-keyframes splash-spin {
  0% { -webkit-transform: rotate(0deg); }
  100% { -webkit-transform: rotate(360deg); }
}
@keyframes splash-spin {
  0% { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}
.live-row .row-icon .row-logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
  pointer-events: none;
}
.pc-row .ic .ic-logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
  pointer-events: none;
}

/* =============================================================================
   WELCOME (Disabled - replaced with EcleX TV background)
   ============================================================================= */
#screen-welcome {
  display: none !important;
  background: #000 url(../media/ui/welcome/eclex_bg.jpg) center center / cover no-repeat;
}
.welcome-name {
  position: absolute;
  left: 0; right: 0;
  top: 625.5px;                     /* 417dp */
  height: 40px;
  font-size: 40.5px;                /* 27sp */
  line-height: 40px;
  text-align: center;
  color: #ffffff;
}
.welcome-version {
  position: absolute;
  left: 0; right: 0;
  top: 692.5px;
  height: 29px;
  font-size: 28.5px;                /* 19sp */
  line-height: 29px;
  text-align: center;
  color: #ffffff;
  opacity: .7;
}
.welcome-loading {
  position: absolute;
  left: 793.5px;                    /* (1920-333)/2 */
  top: 748.5px;
  width: 333px;                     /* 222dp */
  height: 30px;                     /* 20dp  */
}
.welcome-loading img { width: 333px; height: 30px; }

/* =============================================================================
   HOME  (activity_home.xml)
   ============================================================================= */
#screen-home { background: #0b0b0b; }        /* app:defaultBgId color_0b0b0b */

/* ViewPager2 : match_parent, marginTop 93dp
   The pager keeps a 1920x940 viewport and slides the pages inside it. Keeping
   the layer small (instead of a 13440 px wide strip) also stops Chromium from
   rasterising the composited layer at a reduced resolution, which softened
   fine details such as the baked banner titles. */
.home-pages {
  position: absolute;
  left: 0; top: 139.5px;
  width: 1920px; height: 940.5px;
  overflow: hidden;
  -webkit-transition: -webkit-transform .28s cubic-bezier(.25,.1,.25,1);
  transition: transform .28s cubic-bezier(.25,.1,.25,1);
}
.home-page {
  position: absolute;
  left: 0; top: 0;
  width: 1920px; height: 940.5px;
  display: none;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-width: none;
}
.home-page::-webkit-scrollbar {
  display: none;
}
.home-page.is-current { display: block; }
