  box-shadow: 0 4px 24px rgba(0,0,0,0.7);
}
#screen-player.is-mini .player-frame {
  width: 765px;
  height: 430px;
}
#screen-player.is-mini .player-video {
  width: 765px;
  height: 430px;
  object-fit: contain;
}
#screen-player:not(.is-mini) .player-video:not(.aspect-4-3) {
  left: 0;
  top: 0;
  width: 1920px;
  height: 1080px;
}
#screen-player.is-mini .player-status {
  bottom: 24px;
  font-size: 22px;
}
#screen-player.is-mini .player-infobar,
#screen-player.is-mini .player-vod-infobar,
#screen-player.is-mini .player-channels,
#screen-player.is-mini .player-osd-icon {
  display: none !important;
}
/* Original no-data surface, dimmed. Hidden while a real stream is playing. */
.player-frame {
  position: absolute;
  left: 0; top: 0;
  width: 1920px; height: 1080px;
  background: url(../media/ui/common/eclex_bg_blurred.jpg) center center no-repeat;
  background-size: cover;
  opacity: .5;
}
.player-video {
  position: absolute;
  left: 0; top: 0;
  width: 1920px; height: 1080px;
  display: none;
  background: transparent !important;
  z-index: 1 !important;
}
.player-video.is-active { display: block; }
.player-video.aspect-cover { -o-object-fit: cover; object-fit: cover; width: 1920px; height: 1080px; left: 0; }
.player-video.aspect-contain { -o-object-fit: contain; object-fit: contain; width: 1920px; height: 1080px; left: 0; }
.player-video.aspect-16-9 { -o-object-fit: fill; object-fit: fill; width: 1920px; height: 1080px; left: 0; }
.player-video.aspect-4-3 { -o-object-fit: fill; object-fit: fill; width: 1440px; height: 1080px; left: 240px; }
.player-live-loader {
  position: absolute;
  left: 0;
  top: 0;
  width: 1920px;
  height: 1080px;
  display: none;
  z-index: 5;
  pointer-events: none;
  box-sizing: border-box;
}
.player-live-loader.is-visible {
  display: flex !important;
  align-items: center;
  justify-content: center;
}
.live-loader-backdrop {
  position: absolute;
  left: 0;
  top: 0;
  width: 100%;
  height: 100%;
  background: radial-gradient(circle at center, rgba(15, 23, 42, 0.88) 0%, rgba(3, 7, 18, 0.96) 100%);
}
.live-loader-content {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}
.live-loader-spinner {
  width: 68px;
  height: 68px;
  border: 5px solid rgba(0, 230, 118, 0.15);
  border-top-color: #00e676;
  border-radius: 50%;
  -webkit-animation: xuper-loading-spin 0.8s linear infinite;
  animation: xuper-loading-spin 0.8s linear infinite;
  margin-bottom: 24px;
  box-shadow: 0 0 25px rgba(0, 230, 118, 0.35);
}
.live-loader-channel {
  font-size: 36px;
  font-weight: 700;
  color: #ffffff;
  letter-spacing: 0.5px;
  margin-bottom: 10px;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.9);
}
.live-loader-hint {
  font-size: 22px;
  font-weight: 500;
  color: #94a3b8;
  letter-spacing: 0.3px;
}

/* Not in the APK: stream error / preparation feedback. */
.player-status {
  position: absolute;
  left: 0; right: 0;
  bottom: 96px;
  text-align: center;
  color: #ffffff;
  font-size: 30px;
  line-height: 1.3;
  text-shadow: 0 2px 8px rgba(0,0,0,0.85);
  display: none;
  z-index: 6;
  pointer-events: none;
}
.player-status.is-active {
  top: 0;
  bottom: 0;
  display: -webkit-box;
  display: flex;
  -webkit-box-orient: vertical;
  flex-direction: column;
  -webkit-box-pack: center;
  justify-content: center;
  -webkit-box-align: center;
  align-items: center;
  padding: 0 80px;
  box-sizing: border-box;
  background: rgba(8, 14, 28, 0.42);
  font-size: 34px;
  font-weight: 500;
}
.player-status.is-active:before {
  content: '';
  width: 56px;
  height: 56px;
  margin-bottom: 22px;
  border: 5px solid rgba(255,255,255,.28);
  border-top-color: #ffffff;
  border-radius: 50%;
  -webkit-animation: xuper-loading-spin .85s linear infinite;
  animation: xuper-loading-spin .85s linear infinite;
}
@-webkit-keyframes xuper-loading-spin { to { -webkit-transform: rotate(360deg); } }
@keyframes xuper-loading-spin { to { transform: rotate(360deg); } }
.player-status.is-error {
  color: #fca5a5 !important;
  background: rgba(10, 14, 26, 0.75) !important;
  font-size: 38px !important;
  font-weight: bold !important;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.95);
}
.player-status.is-error:before {
  content: '⚠️';
  width: auto !important;
  height: auto !important;
  border: none !important;
  border-radius: 0 !important;
  animation: none !important;
  -webkit-animation: none !important;
  font-size: 60px !important;
  margin-bottom: 16px !important;
}
/* Center OSD status icon (Play / Pause / Seek feedback) */
.player-osd-icon {
  position: absolute;
  left: 50%;
  top: 50%;
  margin-left: -60px;
  margin-top: -60px;
  width: 120px;
  height: 120px;
  background-position: center center;
  background-repeat: no-repeat;
  background-size: contain;
  opacity: 0;
  -webkit-transition: opacity .2s ease;
  transition: opacity .2s ease;
  pointer-events: none;
  z-index: 8;
}
.player-osd-icon.is-active {
  opacity: 1;
}

